import click
import os
import sys

@click.command()
@click.option("--workers", type=click.IntRange(min=1), envvar="BLACK_NUM_WORKERS")
def main(workers):
    print(f"Workers: {workers}")

if __name__ == "__main__":
    if len(sys.argv) > 1:
        os.environ["BLACK_NUM_WORKERS"] = sys.argv[1]
        # Remove the argument so Click doesn't try to parse it as an option
        sys.argv = [sys.argv[0]]
    main()
